-- =============================================================================
-- Transgar - 60: Odometro diario desde 'Control de Combustible' (KM INICIAL / KM FINAL)
-- Un registro por vehiculo+fecha: se toma la fila de MAYOR KM FINAL del dia con su propio
-- par (km_inicial, km_final), evitando spans irreales al mezclar filas. Respeta el indice
-- unico UX_odometro_diario_vehiculo_fecha y el CHECK km_final >= km_inicial.
-- Resuelve vehiculo (numero_interno) y conductor (documento). Requiere 00,20,30.
-- RECARGA LIMPIA: borra los odometros previos de la empresa antes de insertar.
-- =============================================================================
SET QUOTED_IDENTIFIER ON; SET ANSI_NULLS ON; SET NOCOUNT ON;
DECLARE @IdEmpresa INT = (SELECT id_empresa FROM dbo.empresas WHERE codigo='TRANSGAR');
IF @IdEmpresa IS NULL BEGIN RAISERROR('Empresa TRANSGAR no existe. Ejecute 00 primero.',16,1); RETURN; END
DECLARE @Ahora DATETIME2(3)=SYSUTCDATETIME();
DELETE FROM dbo.odometro_diario WHERE id_empresa=@IdEmpresa;
PRINT 'Odometros previos eliminados: '+CAST(@@ROWCOUNT AS varchar(10));
IF OBJECT_ID('tempdb..#odo') IS NOT NULL DROP TABLE #odo;
CREATE TABLE #odo (unidad varchar(20), fecha date, kmini decimal(12,2), kmfin decimal(12,2), doc varchar(30), ruta nvarchar(500));
