INSERT INTO dbo.odometro_diario (id_empresa,id_vehiculo,fecha,km_inicial,km_final,id_conductor,observaciones,eliminado,creado_por,fecha_creacion)
SELECT @IdEmpresa, v.id_vehiculo, o.fecha, o.kmini, o.kmfin, p.id_persona, o.ruta, 0, 'seed-transgar', @Ahora
FROM #odo o
JOIN dbo.vehiculos v ON v.id_empresa=@IdEmpresa AND v.numero_interno=o.unidad AND v.eliminado=0
LEFT JOIN dbo.personas p ON p.id_empresa=@IdEmpresa AND p.documento=o.doc AND p.eliminado=0
WHERE NOT EXISTS (SELECT 1 FROM dbo.odometro_diario x WHERE x.id_empresa=@IdEmpresa AND x.id_vehiculo=v.id_vehiculo AND x.fecha=o.fecha AND x.eliminado=0);
PRINT 'Odometros diarios insertados: '+CAST(@@ROWCOUNT AS varchar(10));
DROP TABLE #odo;
PRINT '=== 60 completado ===';
